1	import { BiomeId, BlockId } from "./blocks";
2	import { VoxelWorld } from "./voxelWorld";
3	import type { WorldType } from "./worldTypes";
4	
5	/**
6	 * Deterministic terrain generation.
7	 *
8	 * ⚠ Saves store only the seed plus block-change deltas, so generateWorld() must
9	 * produce byte-identical output for a given seed forever. Generation order, the
10	 * PRNG, the noise functions, and every constant below are part of the save
11	 * format. generation.test.ts pins the output with SHA-256 digests — if it fails
12	 * after a change here, the change breaks existing saves.
13	 */
14	
15	/**
16	 * Every value here is part of the save format (see module header). Names exist
17	 * for readability; changing a value re-rolls every world.
18	 */
19	export const GEN = Object.freeze({
20	  seaLevel: 43,
21	  borderWallHeight: 14,
22	  biomes: Object.freeze({
23	    [BiomeId.Plains]: Object.freeze({ baseHeight: 47, noiseScale: 2.0, treeChance: 0.18 }),
24	    [BiomeId.Desert]: Object.freeze({ baseHeight: 46, noiseScale: 3.5, treeChance: 0.01 }),
25	    [BiomeId.Ocean]: Object.freeze({ baseHeight: 30, noiseScale: 2.5, treeChance: 0 }),
26	    [BiomeId.Forest]: Object.freeze({ baseHeight: 50, noiseScale: 4.0, treeChance: 0.6 }),
27	    [BiomeId.Mountains]: Object.freeze({ baseHeight: 55, noiseScale: 18.0, treeChance: 0.05 })
28	  }),
29	  mountainStoneAboveY: 65,
30	  snowAboveY: 68,
31	  // Lava pools in the deepest caves: carved air at or below this Y floods with
32	  // lava, well under the surface so it stays a deep-cave hazard.
33	  lavaLevel: 9,
34	  // Sand shoreline band around sea level (deeper floors keep their biome top).
35	  beachMaxAboveSea: 1,
36	  beachDepthBelowSea: 2,
37	  caveCount: 230,
38	  caveChamberCount: 150,
39	  treeAttempts: 9000,
40	  // Cacti per dry desert column — keyed on area so drowned deserts get few.
41	  cactusChance: 0.012,
42	  houseCount: 120,
43	  dungeonCount: 28,
44	  // Villages: clusters of houses (reusing placeHouse) on flat, dry land, placed on
45	  // their own decoupled PRNG (villageRand) so they never shift the shared stream.
46	  // Each valid site seeds a small resident villager population at boot.
47	  villageCount: 12,
48	  villageHouseCount: 5,
49	  villagersPerVillage: 4,
50	  villageMinSpawnDistance: 30,
51	  // A village only lands where the seed-pure surface across its footprint stays
52	  // within this many blocks (so it sits on flat plains/desert, not a mountainside);
53	  // a small terrace then levels the rest, keeping the build natural-looking.
54	  villageFlatnessTolerance: 2,
55	  oreConfigs: Object.freeze([
56	    { id: BlockId.SliverOre, attempts: 120000, minY: 3, maxYOffset: 10, minSize: 3, maxSize: 10 },
57	    { id: BlockId.RubyOre, attempts: 52000, minY: 2, maxYOffset: 16, minSize: 3, maxSize: 10 },
58	    { id: BlockId.GoldOre, attempts: 36000, minY: 2, maxYOffset: 22, minSize: 3, maxSize: 10 },
59	    { id: BlockId.SapphireOre, attempts: 28000, minY: 2, maxYOffset: 28, minSize: 2, maxSize: 7 },
60	    { id: BlockId.DiamondOre, attempts: 18000, minY: 2, maxYOffset: 36, minSize: 2, maxSize: 6 }
61	  ]),
62	  // Coal is placed in its own pass on a dedicated PRNG (see placeCoal) so it never
63	  // shifts the shared `rand` stream — existing ores, trees, and structures stay
64	  // byte-identical to before coal, exactly as deep-cave lava did. It is the
65	  // shallowest, most common ore: large veins reaching near the surface.
66	  coalConfig: Object.freeze({ attempts: 160000, minY: 4, maxYOffset: 8, minSize: 4, maxSize: 12 })
67	});
68	
69	/**
70	 * The terrain-shaping subset of GEN that a world type can vary: sea level and
71	 * per-biome surface height (base + noise amplitude). Everything else (caves,
72	 * ores, lava, trees, structures, dungeons) is type-independent and still reads
73	 * GEN directly. `terrainConfigFor("default")` returns exactly the GEN values, so
74	 * the default world stays byte-identical.
75	 */
76	export type TerrainConfig = {
77	  seaLevel: number;
78	  biomes: Record<BiomeId, { baseHeight: number; noiseScale: number }>;
79	};
80	
81	const BIOME_IDS = [BiomeId.Plains, BiomeId.Desert, BiomeId.Ocean, BiomeId.Forest, BiomeId.Mountains] as const;
82	
83	/** Builds a biome height table from GEN, applying `transform` to each biome's base/scale. */
84	function biomeHeights(
85	  transform: (b: { baseHeight: number; noiseScale: number }, id: BiomeId) => { baseHeight: number; noiseScale: number }
86	): Record<BiomeId, { baseHeight: number; noiseScale: number }> {
87	  const out = {} as Record<BiomeId, { baseHeight: number; noiseScale: number }>;
88	  for (const id of BIOME_IDS) {
89	    const g = GEN.biomes[id];
90	    out[id] = transform({ baseHeight: g.baseHeight, noiseScale: g.noiseScale }, id);
91	  }
92	  return out;
93	}
94	
95	// A raised sea with land biomes lifted so they break the surface as gently
96	// sloped islands (gentle enough that findSpawnOnLand still finds a dry spawn),
97	// while oceans stay as deep channels between them.
98	const ISLANDS_BIOMES: Record<BiomeId, { baseHeight: number; noiseScale: number }> = {
99	  [BiomeId.Plains]: { baseHeight: 54, noiseScale: 4 },
100	  [BiomeId.Desert]: { baseHeight: 52, noiseScale: 3 },
101	  [BiomeId.Ocean]: { baseHeight: 34, noiseScale: 3 },
102	  [BiomeId.Forest]: { baseHeight: 56, noiseScale: 5 },
103	  [BiomeId.Mountains]: { baseHeight: 64, noiseScale: 16 }
104	};
105	
106	/** The terrain config for a world type. "default" returns the GEN values verbatim. */
107	export function terrainConfigFor(worldType: WorldType): TerrainConfig {
108	  switch (worldType) {
109	    case "flat":
110	      // Flat dry ground just above sea level (no water); biome-colored top.
111	      return { seaLevel: GEN.seaLevel, biomes: biomeHeights(() => ({ baseHeight: 48, noiseScale: 0 })) };
112	    case "amplified":
113	      // Exaggerated relief; mountains clamp at the height ceiling as plateaus.
114	      return { seaLevel: GEN.seaLevel, biomes: biomeHeights((b) => ({ baseHeight: b.baseHeight, noiseScale: b.noiseScale * 2 })) };
115	    case "islands":
116	      return { seaLevel: 54, biomes: ISLANDS_BIOMES };
117	    default:
118	      return { seaLevel: GEN.seaLevel, biomes: biomeHeights((b) => b) };
119	  }
120	}
121	
122	function hash2D(x: number, z: number): number {
123	  const n = Math.sin(x * 127.1 + z * 311.7) * 43758.5453123;
124	  return n - Math.floor(n);
125	}
126	
127	function smoothNoise2D(x: number, z: number, seed: number): number {
128	  const s = seed * 0.013;
129	  const val =
130	    Math.sin(x * 0.015 + s) * 1.2 +
131	    Math.cos(z * 0.012 + s * 1.4) * 1.2 +
132	    Math.sin(x * 0.005 - z * 0.007 + s * 0.7) * 3.5 +
133	    Math.cos(x * 0.031 + z * 0.027 + s * 2.1) * 0.4;
134	  return val;
135	}
136	
137	export function generateWorld(world: VoxelWorld, worldType: WorldType = "default"): void {
138	  // Fork on the type up front, before any block write: "default" yields the GEN
139	  // values so its output is byte-identical to before this feature.
140	  const cfg = terrainConfigFor(worldType);
141	
142	  const rand = (() => {
143	    let t = (world.seed >>> 0) + 0x6d2b79f5;
144	    return () => {
145	      t += 0x6d2b79f5;
146	      let r = Math.imul(t ^ (t >>> 15), 1 | t);
147	      r ^= r + Math.imul(r ^ (r >>> 7), 61 | r);
148	      return ((r ^ (r >>> 14)) >>> 0) / 4294967296;
149	    };
150	  })();
151	
152	  generateTerrain(world, cfg);
153	  carveCaves(world, rand);
154	  placeWater(world, cfg);
155	  placeBeaches(world, cfg);
156	  placeOres(world, rand);
157	  // Coal runs on its own PRNG (placeCoal), so it adds ore underground without
158	  // shifting the shared `rand` — trees/structures/dungeons stay byte-identical.
159	  placeCoal(world);
160	  // After placeOres so it can't shift ore RNG (placeOres gates rand on air
161	  // adjacency, which lava would change), and before placeDungeons so dungeon
162	  // rooms — whose floors can sit at or below lavaLevel — overwrite any lava
163	  // rather than flooding. Trees/cacti/houses only read the surface, far above.
164	  placeLava(world);
165	  placeTrees(world, rand);
166	  placeCacti(world);
167	  placeStructures(world, rand);
168	  placeDungeons(world, cfg);
169	  // Villages run LAST on their own decoupled PRNG (villageRand), so they add
170	  // structures without shifting any other stream — every pass above stays
171	  // byte-identical to a village-less world of the same seed.
172	  placeVillages(world, cfg);
173	}
174	
175	function generateTerrain(world: VoxelWorld, cfg: TerrainConfig): void {
176	  const maxX = world.sizeX - 1;
177	  const maxZ = world.sizeZ - 1;
178	
179	  // Fast clear and bedrock
180	  world.blocks.fill(BlockId.Air);
181	  for (let x = 0; x < world.sizeX; x += 1) {
182	    for (let z = 0; z < world.sizeZ; z += 1) {
183	      world.set(x, 0, z, BlockId.Bedrock);
184	    }
185	  }
186	
187	  for (let x = 0; x < world.sizeX; x += 1) {
188	    for (let z = 0; z < world.sizeZ; z += 1) {
189	      const biome = world.getBiome(x, z);
190	      const noise = smoothNoise2D(x, z, world.seed);
191	      const { baseHeight, noiseScale } = cfg.biomes[biome];
192	
193	      const topY = Math.max(5, Math.min(world.sizeY - 5, Math.floor(baseHeight + noise * noiseScale)));
194	      let topBlock = BlockId.Grass;
195	      if (biome === BiomeId.Desert || biome === BiomeId.Ocean) {
196	        topBlock = BlockId.Sand;
197	      } else if (biome === BiomeId.Mountains && topY > GEN.snowAboveY) {
198	        topBlock = BlockId.Snow;
199	      } else if (biome === BiomeId.Mountains && topY > GEN.mountainStoneAboveY) {
200	        topBlock = BlockId.Stone;
201	      }
202	
203	      for (let y = 1; y <= topY; y += 1) {
204	        if (y === topY) {
205	          world.set(x, y, z, topBlock);
206	        } else if (y > topY - 3) {
207	          world.set(x, y, z, topBlock === BlockId.Sand ? BlockId.Sand : BlockId.Dirt);
208	        } else if (y > topY - 8 && hash2D(x * 0.2 + y * 0.1, z * 0.2) > 0.88) {
209	          world.set(x, y, z, BlockId.Cobblestone);
210	        } else {
211	          world.set(x, y, z, BlockId.Stone);
212	        }
213	      }
214	    }
215	  }
216	
217	  // Unbreakable border walls.
218	  for (let y = 1; y <= GEN.borderWallHeight; y += 1) {
219	    for (let x = 0; x < world.sizeX; x += 1) {
220	      world.set(x, y, 0, BlockId.Bedrock);
221	      world.set(x, y, maxZ, BlockId.Bedrock);
222	    }
223	    for (let z = 0; z < world.sizeZ; z += 1) {
224	      world.set(0, y, z, BlockId.Bedrock);
225	      world.set(maxX, y, z, BlockId.Bedrock);
226	    }
227	  }
228	}
229	
230	function carveCaves(world: VoxelWorld, rand: () => number): void {
231	  const carveSphere = (cx: number, cy: number, cz: number, radius: number) => {
232	    const r2 = radius * radius;
233	    const minX = Math.max(1, Math.floor(cx - radius));
234	    const maxXc = Math.min(world.sizeX - 2, Math.ceil(cx + radius));
235	    const minY = Math.max(1, Math.floor(cy - radius));
236	    const maxYc = Math.min(world.sizeY - 2, Math.ceil(cy + radius));
237	    const minZ = Math.max(1, Math.floor(cz - radius));
238	    const maxZc = Math.min(world.sizeZ - 2, Math.ceil(cz + radius));
239	    for (let y = minY; y <= maxYc; y += 1) {
240	      for (let z = minZ; z <= maxZc; z += 1) {
241	        for (let x = minX; x <= maxXc; x += 1) {
242	          const dx = x - cx;
243	          const dy = y - cy;
244	          const dz = z - cz;
245	          if (dx * dx + dy * dy + dz * dz > r2) continue;
246	          const block = world.get(x, y, z);
247	          if (block !== BlockId.Bedrock) world.set(x, y, z, BlockId.Air);
248	        }
249	      }
250	    }
251	  };
252	
253	  for (let i = 0; i < GEN.caveCount; i += 1) {
254	    let x = 12 + rand() * (world.sizeX - 24);
255	    let y = 3 + rand() * (world.sizeY - 9);
256	    let z = 12 + rand() * (world.sizeZ - 24);
257	    let yaw = rand() * Math.PI * 2;
258	    let pitch = (rand() - 0.5) * 0.26;
259	    const length = 56 + Math.floor(rand() * 56);
260	    for (let step = 0; step < length; step += 1) {
261	      const r = 1.9 + rand() * 2.6;
262	      carveSphere(x, y, z, r);
263	      if (rand() > 0.968) carveSphere(x, y, z, 4.8 + rand() * 4.6);
264	      yaw += (rand() - 0.5) * 0.28;
265	      pitch = Math.max(-0.55, Math.min(0.55, pitch + (rand() - 0.5) * 0.16));
266	      x += Math.cos(yaw);
267	      z += Math.sin(yaw);
268	      y += Math.sin(pitch) * 0.8;
269	      if (x < 8 || x > world.sizeX - 8 || z < 8 || z > world.sizeZ - 8 || y < 2 || y > world.sizeY - 4) break;
270	    }
271	  }
272	
273	  for (let i = 0; i < GEN.caveChamberCount; i += 1) {
274	    const cx = 12 + rand() * (world.sizeX - 24);
275	    const cy = 5 + rand() * (world.sizeY - 14);
276	    const cz = 12 + rand() * (world.sizeZ - 24);
277	    carveSphere(cx, cy, cz, 5.4 + rand() * 6.4);
278	  }
279	}
280	
281	function placeLava(world: VoxelWorld): void {
282	  const { lavaLevel } = GEN;
283	  for (let x = 1; x < world.sizeX - 1; x += 1) {
284	    for (let z = 1; z < world.sizeZ - 1; z += 1) {
285	      for (let y = 1; y <= lavaLevel; y += 1) {
286	        if (world.get(x, y, z) === BlockId.Air) world.set(x, y, z, BlockId.Lava);
287	      }
288	    }
289	  }
290	}
291	
292	function placeWater(world: VoxelWorld, cfg: TerrainConfig): void {
293	  const { seaLevel } = cfg;
294	  for (let x = 1; x < world.sizeX - 1; x += 1) {
295	    for (let z = 1; z < world.sizeZ - 1; z += 1) {
296	      const topY = world.highestSolidY(x, z);
297	      if (topY >= seaLevel) continue;
298	      for (let y = topY + 1; y <= seaLevel; y += 1) {
299	        if (world.get(x, y, z) === BlockId.Air) world.set(x, y, z, BlockId.Water);
300	      }
301	    }
302	  }
303	}
304	
305	function placeOres(world: VoxelWorld, rand: () => number): void {
306	  const hasNearbyAir = (x: number, y: number, z: number): boolean => {
307	    return (
308	      world.get(x + 1, y, z) === BlockId.Air ||
309	      world.get(x - 1, y, z) === BlockId.Air ||
310	      world.get(x, y + 1, z) === BlockId.Air ||
311	      world.get(x, y - 1, z) === BlockId.Air ||
312	      world.get(x, y, z + 1) === BlockId.Air ||
313	      world.get(x, y, z - 1) === BlockId.Air ||
314	      world.get(x + 1, y, z) === BlockId.Water ||
315	      world.get(x - 1, y, z) === BlockId.Water ||
316	      world.get(x, y + 1, z) === BlockId.Water ||
317	      world.get(x, y - 1, z) === BlockId.Water ||
318	      world.get(x, y, z + 1) === BlockId.Water ||
319	      world.get(x, y, z - 1) === BlockId.Water
320	    );
321	  };
322	
323	  const placeOreVein = (x: number, y: number, z: number, ore: BlockId, minSize: number, maxSize: number) => {
324	    const size = minSize + Math.floor(rand() * Math.max(1, maxSize - minSize + 1));
325	    for (let i = 0; i < size; i += 1) {
326	      const vx = x + Math.floor((rand() - 0.5) * 4);
327	      const vy = y + Math.floor((rand() - 0.5) * 3);
328	      const vz = z + Math.floor((rand() - 0.5) * 4);
329	      if (!world.inBounds(vx, vy, vz) || vy <= 1) continue;
330	      const b = world.get(vx, vy, vz);
331	      if (b === BlockId.Stone || b === BlockId.Cobblestone) world.set(vx, vy, vz, ore);
332	    }
333	  };
334	
335	  for (const config of GEN.oreConfigs) {
336	    for (let i = 0; i < config.attempts; i += 1) {
337	      const x = 8 + Math.floor(rand() * (world.sizeX - 16));
338	      const y = config.minY + Math.floor(rand() * Math.max(2, world.sizeY - config.maxYOffset));
339	      const z = 8 + Math.floor(rand() * (world.sizeZ - 16));
340	      const block = world.get(x, y, z);
341	      if ((block !== BlockId.Stone && block !== BlockId.Cobblestone) || !hasNearbyAir(x, y, z)) continue;
342	      placeOreVein(x, y, z, config.id, config.minSize, config.maxSize);
343	    }
344	  }
345	}
346	
347	/** A coal-only PRNG seeded from the world seed, decoupled from the main gen stream. */
348	function coalRand(seed: number): () => number {
349	  let t = (seed ^ 0x85ebca6b) >>> 0;
350	  return () => {
351	    t += 0x6d2b79f5;
352	    let r = Math.imul(t ^ (t >>> 15), 1 | t);
353	    r ^= r + Math.imul(r ^ (r >>> 7), 61 | r);
354	    return ((r ^ (r >>> 14)) >>> 0) / 4294967296;
355	  };
356	}
357	
358	/**
359	 * Coal veins, placed on their own PRNG so the pass never consumes from the shared
360	 * `rand` stream — every other ore, tree, and structure stays byte-identical to a
361	 * coal-free world. Like the other ores, coal only replaces stone/cobblestone.
362	 */
363	function placeCoal(world: VoxelWorld): void {
364	  const rand = coalRand(world.seed);
365	  const cfg = GEN.coalConfig;
366	  const placeVein = (x: number, y: number, z: number) => {
367	    const size = cfg.minSize + Math.floor(rand() * Math.max(1, cfg.maxSize - cfg.minSize + 1));
368	    for (let i = 0; i < size; i += 1) {
369	      const vx = x + Math.floor((rand() - 0.5) * 4);
370	      const vy = y + Math.floor((rand() - 0.5) * 3);
371	      const vz = z + Math.floor((rand() - 0.5) * 4);
372	      if (!world.inBounds(vx, vy, vz) || vy <= 1) continue;
373	      const b = world.get(vx, vy, vz);
374	      if (b === BlockId.Stone || b === BlockId.Cobblestone) world.set(vx, vy, vz, BlockId.CoalOre);
375	    }
376	  };
377	  for (let i = 0; i < cfg.attempts; i += 1) {
378	    const x = 8 + Math.floor(rand() * (world.sizeX - 16));
379	    const y = cfg.minY + Math.floor(rand() * Math.max(2, world.sizeY - cfg.maxYOffset));
380	    const z = 8 + Math.floor(rand() * (world.sizeZ - 16));
381	    const block = world.get(x, y, z);
382	    if (block !== BlockId.Stone && block !== BlockId.Cobblestone) continue;
383	    placeVein(x, y, z);
384	  }
385	}
386	
387	/**
388	 * Sand shorelines: grass columns in the sea-level band turn to beach only
389	 * when water actually sits nearby — inland basins at sea level stay grass.
390	 * Runs after placeWater so adjacency can test real water blocks.
391	 */
392	function placeBeaches(world: VoxelWorld, cfg: TerrainConfig): void {
393	  const { seaLevel } = cfg;
394	  for (let x = 1; x < world.sizeX - 1; x += 1) {
395	    for (let z = 1; z < world.sizeZ - 1; z += 1) {
396	      const topY = world.highestSolidY(x, z);
397	      if (topY > seaLevel + GEN.beachMaxAboveSea || topY < seaLevel - GEN.beachDepthBelowSea) continue;
398	      if (world.get(x, topY, z) !== BlockId.Grass) continue;
399	
400	      let nearWater = false;
401	      for (let dx = -2; dx <= 2 && !nearWater; dx += 1) {
402	        for (let dz = -2; dz <= 2 && !nearWater; dz += 1) {
403	          if (world.get(x + dx, seaLevel, z + dz) === BlockId.Water) nearWater = true;
404	        }
405	      }
406	      if (!nearWater) continue;
407	
408	      for (let y = Math.max(1, topY - 2); y <= topY; y += 1) world.set(x, y, z, BlockId.Sand);
409	    }
410	  }
411	}
412	
413	function placeTrees(world: VoxelWorld, rand: () => number): void {
414	  for (let i = 0; i < GEN.treeAttempts; i += 1) {
415	    const x = 4 + Math.floor(rand() * (world.sizeX - 8));
416	    const z = 4 + Math.floor(rand() * (world.sizeZ - 8));
417	
418	    const biome = world.getBiome(x, z);
419	    const spawnChance = GEN.biomes[biome].treeChance;
420	
421	    if (rand() > spawnChance) continue;
422	
423	    const topY = world.highestSolidY(x, z);
424	    if (world.get(x, topY, z) !== BlockId.Grass) continue;
425	
426	    const trunkHeight = spawnChance > 0.5 ? 4 + Math.floor(rand() * 3) : 3 + Math.floor(rand() * 3);
427	    for (let y = 1; y <= trunkHeight; y += 1) world.set(x, topY + y, z, BlockId.Wood);
428	
429	    const leafStart = topY + trunkHeight - 1;
430	    for (let ox = -2; ox <= 2; ox += 1) {
431	      for (let oz = -2; oz <= 2; oz += 1) {
432	        for (let oy = 0; oy <= 2; oy += 1) {
433	          const d = Math.abs(ox) + Math.abs(oz) + oy;
434	          if (d > 4) continue;
435	          // Only fill air: the canopy must not eat the trunk or neighbors.
436	          if (world.get(x + ox, leafStart + oy, z + oz) !== BlockId.Air) continue;
437	          world.set(x + ox, leafStart + oy, z + oz, BlockId.Leaves);
438	        }
439	      }
440	    }
441	  }
442	}
443	
444	function placeCacti(world: VoxelWorld): void {
445	  // Hash-gated scan instead of random attempts: density follows the dry
446	  // desert area, so a mostly-flooded desert gets few cacti instead of the
447	  // whole budget missing. Doesn't consume the shared rand stream.
448	  for (let x = 4; x < world.sizeX - 4; x += 1) {
449	    for (let z = 4; z < world.sizeZ - 4; z += 1) {
450	      if (hash2D(x * 1.7 + 11.3, z * 2.3 - 7.1) > GEN.cactusChance) continue;
451	      if (world.getBiome(x, z) !== BiomeId.Desert) continue;
452	
453	      const topY = world.highestSolidY(x, z);
454	      if (world.get(x, topY, z) !== BlockId.Sand) continue;
455	      if (world.get(x, topY + 1, z) !== BlockId.Air) continue;
456	
457	      const height = 2 + (hash2D(z * 3.1, x * 1.3) > 0.5 ? 1 : 0);
458	      for (let y = 1; y <= height; y += 1) world.set(x, topY + y, z, BlockId.Cactus);
459	    }
460	  }
461	}
462	
463	function placeStructures(world: VoxelWorld, rand: () => number): void {
464	  for (let i = 0; i < GEN.houseCount; i += 1) {
465	    const cx = 12 + Math.floor(rand() * (world.sizeX - 24));
466	    const cz = 12 + Math.floor(rand() * (world.sizeZ - 24));
467	    placeHouse(world, cx, cz);
468	  }
469	}
470	
471	function placeHouse(world: VoxelWorld, cx: number, cz: number): void {
472	  const half = 3;
473	  const floorY = world.highestSolidY(cx, cz) + 1;
474	  if (floorY < 3 || floorY + 6 >= world.sizeY - 1) return;
475	
476	  for (let x = cx - half - 1; x <= cx + half + 1; x += 1) {
477	    for (let z = cz - half - 1; z <= cz + half + 1; z += 1) {
478	      if (!world.inBounds(x, floorY - 1, z)) return;
479	      const y = world.highestSolidY(x, z);
480	      if (Math.abs(y - (floorY - 1)) > 1) return;
481	    }
482	  }
483	
484	  buildHouseShell(world, cx, cz, floorY);
485	}
486	
487	/**
488	 * Builds the house itself at a pre-validated `floorY` (cobblestone floor pad,
489	 * brick walls with glass windows, wood corner posts, a door gap, and a plank
490	 * roof). Split out of placeHouse so villages can level a pad and build on it.
491	 */
492	function buildHouseShell(world: VoxelWorld, cx: number, cz: number, floorY: number): void {
493	  const half = 3;
494	  for (let x = cx - half; x <= cx + half; x += 1) {
495	    for (let z = cz - half; z <= cz + half; z += 1) world.set(x, floorY - 1, z, BlockId.Cobblestone);
496	  }
497	
498	  for (let y = floorY; y <= floorY + 3; y += 1) {
499	    for (let x = cx - half; x <= cx + half; x += 1) {
500	      for (let z = cz - half; z <= cz + half; z += 1) {
501	        const wall = x === cx - half || x === cx + half || z === cz - half || z === cz + half;
502	        if (!wall) continue;
503	        const isWindow = y === floorY + 1 && ((x === cx && (z === cz - half || z === cz + half)) || (z === cz && (x === cx - half || x === cx + half)));
504	        world.set(x, y, z, isWindow ? BlockId.Glass : BlockId.Brick);
505	      }
506	    }
507	  }
508	
509	  world.set(cx, floorY + 1, cz - half, BlockId.Air);
510	  world.set(cx, floorY + 2, cz - half, BlockId.Air);
511	
512	  for (let y = floorY; y <= floorY + 3; y += 1) {
513	    world.set(cx - half, y, cz - half, BlockId.Wood);
514	    world.set(cx + half, y, cz - half, BlockId.Wood);
515	    world.set(cx - half, y, cz + half, BlockId.Wood);
516	    world.set(cx + half, y, cz + half, BlockId.Wood);
517	  }
518	
519	  for (let x = cx - half - 1; x <= cx + half + 1; x += 1) {
520	    for (let z = cz - half - 1; z <= cz + half + 1; z += 1) world.set(x, floorY + 4, z, BlockId.Planks);
521	  }
522	}
523	
524	// ── Dungeons ──────────────────────────────────────────────────────────────
525	// Small underground cobblestone rooms with pre-fillable loot chests and a mob
526	// spawner. The chest CONTENTS are not generated here (the block-diff save can't
527	// carry worldgen-placed entities), only the blocks — the engine fills chests
528	// lazily on first open. To support that, the engine re-derives the chest and
529	// spawner voxel indices on load via collectDungeonSites(), which replays this
530	// exact placement math. Two invariants keep build and derive in lockstep:
531	//   1. A dedicated PRNG seeded only from world.seed (independent of the shared
532	//      generation stream), and every dungeon draws a fixed number of values up
533	//      front so the stream stays aligned whether or not the dungeon is placed.
534	//   2. Placement validates against terrainTopY() — a seed-pure surface estimate
535	//      — never highestSolidY(), which a cave or a player edit could shift.
536	
537	type DungeonSink = { chest: (idx: number) => void; spawner: (idx: number) => void };
538	
539	const NOOP_DUNGEON_SINK: DungeonSink = { chest: () => {}, spawner: () => {} };
540	
541	/** A PRNG seeded only from the world seed, decoupled from the main gen stream. */
542	function dungeonRand(seed: number): () => number {
543	  let t = (seed ^ 0x9e3779b9) >>> 0;
544	  return () => {
545	    t += 0x6d2b79f5;
546	    let r = Math.imul(t ^ (t >>> 15), 1 | t);
547	    r ^= r + Math.imul(r ^ (r >>> 7), 61 | r);
548	    return ((r ^ (r >>> 14)) >>> 0) / 4294967296;
549	  };
550	}
551	
552	/**
553	 * The generation-time terrain surface at (x,z), computed purely from the seed
554	 * (mirrors the topY math in generateTerrain). Unlike highestSolidY it reads no
555	 * blocks, so it is identical at generation and at load — the property that lets
556	 * collectDungeonSites reproduce the exact dungeon layout.
557	 */
558	function terrainTopY(world: VoxelWorld, x: number, z: number, cfg: TerrainConfig): number {
559	  const biome = world.getBiome(x, z);
560	  const noise = smoothNoise2D(x, z, world.seed);
561	  const { baseHeight, noiseScale } = cfg.biomes[biome];
562	  return Math.max(5, Math.min(world.sizeY - 5, Math.floor(baseHeight + noise * noiseScale)));
563	}
564	
565	function buildDungeonRoom(world: VoxelWorld, cx: number, cz: number, floorY: number, secondChest: boolean, write: boolean, sink: DungeonSink): void {
566	  const half = 3; // 7x7 outer, 5x5x4 hollow interior
567	  if (write) {
568	    for (let y = floorY - 1; y <= floorY + 4; y += 1) {
569	      for (let x = cx - half; x <= cx + half; x += 1) {
570	        for (let z = cz - half; z <= cz + half; z += 1) {
571	          if (!world.inBounds(x, y, z)) continue;
572	          const interior = x > cx - half && x < cx + half && z > cz - half && z < cz + half && y >= floorY && y <= floorY + 3;
573	          if (interior) {
574	            world.set(x, y, z, BlockId.Air);
575	          } else {
576	            const mossy = hash2D(x * 1.7 + y * 0.9, z * 2.3 - y * 0.6) > 0.6;
577	            world.set(x, y, z, mossy ? BlockId.MossyCobblestone : BlockId.Cobblestone);
578	          }
579	        }
580	      }
581	    }
582	    world.set(cx - 2, floorY, cz - 2, BlockId.Chest);
583	    if (secondChest) world.set(cx + 2, floorY, cz + 2, BlockId.Chest);
584	    world.set(cx, floorY, cz, BlockId.Spawner);
585	  }
586	  sink.chest(world.index(cx - 2, floorY, cz - 2));
587	  if (secondChest) sink.chest(world.index(cx + 2, floorY, cz + 2));
588	  sink.spawner(world.index(cx, floorY, cz));
589	}
590	
591	function buildDungeons(world: VoxelWorld, write: boolean, sink: DungeonSink, cfg: TerrainConfig): void {
592	  const rand = dungeonRand(world.seed);
593	  const centerX = world.sizeX / 2;
594	  const centerZ = world.sizeZ / 2;
595	  for (let i = 0; i < GEN.dungeonCount; i += 1) {
596	    // Draw every random up front so the stream advances identically whether or
597	    // not this dungeon turns out to be placeable.
598	    const cx = 12 + Math.floor(rand() * (world.sizeX - 24));
599	    const cz = 12 + Math.floor(rand() * (world.sizeZ - 24));
600	    const floorRoll = rand();
601	    const secondChest = rand() < 0.6;
602	
603	    const surface = terrainTopY(world, cx, cz, cfg);
604	    const minFloor = 7;
605	    const maxFloor = surface - 7; // keep the ceiling >=3 below the surface
606	    if (maxFloor < minFloor) continue;
607	    // Keep dungeons clear of the spawn area so there's no free starter loot.
608	    if (Math.hypot(cx - centerX, cz - centerZ) < 40) continue;
609	
610	    const floorY = minFloor + Math.floor(floorRoll * (maxFloor - minFloor + 1));
611	    buildDungeonRoom(world, cx, cz, floorY, secondChest, write, sink);
612	  }
613	}
614	
615	function placeDungeons(world: VoxelWorld, cfg: TerrainConfig): void {
616	  buildDungeons(world, true, NOOP_DUNGEON_SINK, cfg);
617	}
618	
619	export type DungeonSites = { chestIndices: number[]; spawnerIndices: number[] };
620	
621	/**
622	 * Re-derives the voxel indices of every dungeon chest and spawner WITHOUT
623	 * writing blocks, by replaying buildDungeons' placement math. The engine calls
624	 * this once after regenerating the world on load to rebuild the session-only
625	 * dungeon index sets that gate lazy loot fill and spawner activation. It must be
626	 * passed the same worldType the world was generated with — dungeon depths follow
627	 * the type's terrain, so the derived indices match what placeDungeons wrote.
628	 */
629	export function collectDungeonSites(world: VoxelWorld, worldType: WorldType = "default"): DungeonSites {
630	  const chestIndices: number[] = [];
631	  const spawnerIndices: number[] = [];
632	  buildDungeons(world, false, { chest: (idx) => chestIndices.push(idx), spawner: (idx) => spawnerIndices.push(idx) }, terrainConfigFor(worldType));
633	  return { chestIndices, spawnerIndices };
634	}
635	
636	// ── Villages ────────────────────────────────────────────────────────────────
637	// Clusters of houses on flat, dry land. Like dungeons, the world's block diff
638	// can't carry the resident villagers, so the engine re-derives each village's
639	// center on load (collectVillageSites) and seeds residents there. The same two
640	// invariants keep build and derive in lockstep: a dedicated PRNG seeded only from
641	// world.seed, with a fixed number of draws per village; and seed-pure validation
642	// via terrainTopY (never highestSolidY, which caves/edits could shift).
643	
644	/** Resident-spawn centers a village contributes (one per placed village). */
645	type VillageSink = (cx: number, cz: number) => void;
646	const NOOP_VILLAGE_SINK: VillageSink = () => {};
647	
648	/** House offsets from the village center — a tidy cross (center + four arms), spaced so 7-wide footprints don't overlap. */
649	const VILLAGE_HOUSE_OFFSETS: ReadonlyArray<readonly [number, number]> = [
650	  [0, 0],
651	  [9, 0],
652	  [-9, 0],
653	  [0, 9],
654	  [0, -9],
655	  [9, 9],
656	  [-9, -9],
657	  [9, -9],
658	  [-9, 9]
659	];
660	
661	/** A PRNG seeded only from the world seed, decoupled from the main gen and dungeon streams. */
662	function villageRand(seed: number): () => number {
663	  let t = (seed ^ 0x85ebca6b) >>> 0;
664	  return () => {
665	    t += 0x6d2b79f5;
666	    let r = Math.imul(t ^ (t >>> 15), 1 | t);
667	    r ^= r + Math.imul(r ^ (r >>> 7), 61 | r);
668	    return ((r ^ (r >>> 14)) >>> 0) / 4294967296;
669	  };
670	}
671	
672	/**
673	 * Seed-pure flatness gate: true when the surface under every house in the village
674	 * stays within villageFlatnessTolerance of the center's floor. Reads only
675	 * terrainTopY (no blocks), so build and derive agree on which villages exist.
676	 */
677	function villageGroundFlat(world: VoxelWorld, cx: number, cz: number, baseSurface: number, cfg: TerrainConfig): boolean {
678	  for (let h = 0; h < GEN.villageHouseCount; h += 1) {
679	    const [ox, oz] = VILLAGE_HOUSE_OFFSETS[h];
680	    if (!world.inBounds(cx + ox, baseSurface, cz + oz)) return false;
681	    if (Math.abs(terrainTopY(world, cx + ox, cz + oz, cfg) - baseSurface) > GEN.villageFlatnessTolerance) return false;
682	  }
683	  return true;
684	}
685	
686	/** Levels a 9×9 pad to `floorY-1` (clearing terrain bumps above, filling just below) and builds a house on it. */
687	function buildVillageHouse(world: VoxelWorld, cx: number, cz: number, floorY: number): void {
688	  const pad = 4; // house footprint half-width plus its border
689	  for (let x = cx - pad; x <= cx + pad; x += 1) {
690	    for (let z = cz - pad; z <= cz + pad; z += 1) {
691	      if (!world.inBounds(x, floorY - 1, z)) return;
692	      world.set(x, floorY - 2, z, BlockId.Dirt);
693	      world.set(x, floorY - 1, z, BlockId.Grass);
694	      for (let y = floorY; y <= floorY + 5; y += 1) world.set(x, y, z, BlockId.Air);
695	    }
696	  }
697	  buildHouseShell(world, cx, cz, floorY);
698	}
699	
700	function buildVillages(world: VoxelWorld, write: boolean, sink: VillageSink, cfg: TerrainConfig): void {
701	  const rand = villageRand(world.seed);
702	  const centerX = world.sizeX / 2;
703	  const centerZ = world.sizeZ / 2;
704	  for (let i = 0; i < GEN.villageCount; i += 1) {
705	    // Draw every random up front so the stream advances identically whether or
706	    // not this village turns out to be placeable.
707	    const cx = 20 + Math.floor(rand() * (world.sizeX - 40));
708	    const cz = 20 + Math.floor(rand() * (world.sizeZ - 40));
709	
710	    const surface = terrainTopY(world, cx, cz, cfg);
711	    // Dry, buildable land only (above sea level, not into the sky), clear of the
712	    // spawn area, and flat enough across the whole footprint — all seed-pure, so
713	    // the record pass derives the exact same set of villages the write pass built.
714	    if (surface <= cfg.seaLevel || surface >= world.sizeY - 8) continue;
715	    if (Math.hypot(cx - centerX, cz - centerZ) < GEN.villageMinSpawnDistance) continue;
716	    if (!villageGroundFlat(world, cx, cz, surface, cfg)) continue;
717	
718	    if (write) {
719	      const floorY = surface + 1;
720	      for (let h = 0; h < GEN.villageHouseCount; h += 1) {
721	        const [ox, oz] = VILLAGE_HOUSE_OFFSETS[h];
722	        buildVillageHouse(world, cx + ox, cz + oz, floorY);
723	      }
724	      // Cobblestone paths along the cross arms tie the houses into one settlement.
725	      for (let d = -9; d <= 9; d += 1) {
726	        if (world.inBounds(cx + d, floorY - 1, cz)) world.set(cx + d, floorY - 1, cz, BlockId.Cobblestone);
727	        if (world.inBounds(cx, floorY - 1, cz + d)) world.set(cx, floorY - 1, cz + d, BlockId.Cobblestone);
728	      }
729	    }
730	    sink(cx, cz);
731	  }
732	}
733	
734	function placeVillages(world: VoxelWorld, cfg: TerrainConfig): void {
735	  buildVillages(world, true, NOOP_VILLAGE_SINK, cfg);
736	}
737	
738	export type VillageSites = { centers: Array<{ x: number; z: number }> };
739	
740	/**
741	 * Re-derives every village's center WITHOUT writing blocks, by replaying
742	 * buildVillages' placement math. The engine calls this once after regenerating
743	 * the world on load to rebuild the session-only village sites that seed resident
744	 * villagers. Must be passed the same worldType the world was generated with.
745	 */
746	export function collectVillageSites(world: VoxelWorld, worldType: WorldType = "default"): VillageSites {
747	  const centers: Array<{ x: number; z: number }> = [];
748	  buildVillages(world, false, (x, z) => centers.push({ x, z }), terrainConfigFor(worldType));
749	  return { centers };
750	}
