1	import { describe, expect, test } from "bun:test";
2	import {
3	  BiomeId,
4	  BlockId,
5	  VoxelWorld,
6	  buildGeometryLayersRegion,
7	  buildGeometryRegion,
8	  collectDungeonSites,
9	  collectVillageSites,
10	  computeFullLight,
11	  generateWorld,
12	  type WorldType
13	} from "@/lib/world";
14	import { GEN } from "@/lib/world/generation";
15	
16	/**
17	 * Worldgen determinism characterization tests.
18	 *
19	 * Saves store only the seed plus block-change deltas, so world generation must
20	 * produce byte-identical output for a given seed forever. These digests pin the
21	 * current generator output.
22	 *
23	 * If a test here fails after a refactor, THE REFACTOR BROKE SAVE COMPATIBILITY —
24	 * fix the code, never the hash. Re-baselining is only legitimate for a deliberate,
25	 * CHANGELOG-flagged worldgen change, or for a Bun/JSC engine bump (the noise
26	 * functions use Math.sin, whose exact results are engine-defined; CI pins the Bun
27	 * version for this reason — see docs/testing.md).
28	 */
29	
30	function hashBytes(bytes: Uint8Array): string {
31	  return new Bun.CryptoHasher("sha256").update(bytes).digest("hex");
32	}
33	
34	function makeWorld(sizeX: number, sizeY: number, sizeZ: number, seed: number): VoxelWorld {
35	  const world = new VoxelWorld(sizeX, sizeY, sizeZ, seed);
36	  generateWorld(world);
37	  return world;
38	}
39	
40	function makeTypedWorld(sizeX: number, sizeY: number, sizeZ: number, seed: number, worldType: WorldType): VoxelWorld {
41	  const world = new VoxelWorld(sizeX, sizeY, sizeZ, seed);
42	  generateWorld(world, worldType);
43	  return world;
44	}
45	
46	const GROUND_BLOCKS = new Set<number>([BlockId.Grass, BlockId.Sand, BlockId.Dirt, BlockId.Stone, BlockId.Cobblestone, BlockId.Snow]);
47	
48	/** Highest terrain (ground) block in a column, ignoring trees/water/air — the visible surface. */
49	function groundHeight(world: VoxelWorld, x: number, z: number): number {
50	  for (let y = world.sizeY - 1; y >= 0; y -= 1) {
51	    if (GROUND_BLOCKS.has(world.get(x, y, z))) return y;
52	  }
53	  return 0;
54	}
55	
56	let fullWorldCache: VoxelWorld | null = null;
57	function fullWorld(): VoxelWorld {
58	  fullWorldCache ??= makeWorld(512, 150, 512, 1337);
59	  return fullWorldCache;
60	}
61	
62	describe("worldgen determinism", () => {
63	  test.each([
64	    [1337, "b68e443c2baf43ddb0d522e595a2c66dc5b23f5fc06c25ebae2af07812525f25"],
65	    [1, "9af01515475054435df4789163f088c3362f594789629f6c326bed53576961f8"],
66	    [999999937, "a17c2e5610b7eb9dbfd6c5952d15e81b968b07e9a22adb9667b6fe5249004852"]
67	  ])("128x150x128 world for seed %d is byte-identical", (seed, expected) => {
68	    expect(hashBytes(makeWorld(128, 150, 128, seed).blocks)).toBe(expected);
69	  });
70	
71	  test(
72	    "full-size 512x150x512 world for seed 1337 is byte-identical (the real save-compat surface)",
73	    () => {
74	      expect(hashBytes(fullWorld().blocks)).toBe("48bf16c8019ef76bb9b034942f88542a88785538d29c09bf6100f8a30d0831f2");
75	    },
76	    { timeout: 60000 }
77	  );
78	
79	  // Probes that survive a legitimate re-baseline: they describe the shape of the
80	  // world rather than its exact bytes, and localize a failure when the hash differs.
81	  test("structural probes for seed 1337", () => {
82	    const world = fullWorld();
83	
84	    // Bedrock floor everywhere and border walls up to y=14.
85	    expect(world.get(5, 0, 5)).toBe(BlockId.Bedrock);
86	    expect(world.get(300, 0, 300)).toBe(BlockId.Bedrock);
87	    expect(world.get(0, 10, 100)).toBe(BlockId.Bedrock);
88	    expect(world.get(511, 14, 200)).toBe(BlockId.Bedrock);
89	    expect(world.get(200, 14, 0)).toBe(BlockId.Bedrock);
90	
91	    // Biome field samples.
92	    expect(world.getBiome(1, 1)).toBe(BiomeId.Forest);
93	    expect(world.getBiome(1, 277)).toBe(BiomeId.Desert);
94	    expect(world.getBiome(400, 100)).toBe(BiomeId.Mountains);
95	
96	    // Terrain heights at sample columns ((64,64) tops out in a tree canopy).
97	    expect(world.highestSolidY(64, 64)).toBe(49);
98	    expect(world.highestSolidY(256, 256)).toBe(28);
99	    expect(world.highestSolidY(400, 100)).toBe(104);
100	
101	    // Snow caps above the snow line.
102	    expect(world.get(400, 104, 100)).toBe(BlockId.Snow);
103	
104	    // Sea-level fill: a column whose floor is below sea level holds water at y=43.
105	    expect(world.highestSolidY(1, 277)).toBe(30);
106	    expect(world.get(1, 43, 277)).toBe(BlockId.Water);
107	
108	    // Lava pools in the deepest caves only — present, and never above lavaLevel.
109	    let lavaCells = 0;
110	    let maxLavaY = -1;
111	    const layer = world.sizeX * world.sizeZ;
112	    for (let i = 0; i < world.blocks.length; i += 1) {
113	      if (world.blocks[i] === BlockId.Lava) {
114	        lavaCells += 1;
115	        const ly = Math.floor(i / layer);
116	        if (ly > maxLavaY) maxLavaY = ly;
117	      }
118	    }
119	    expect(lavaCells).toBeGreaterThan(0);
120	    expect(maxLavaY).toBeLessThanOrEqual(9); // GEN.lavaLevel
121	  });
122	});
123	
124	describe("world types", () => {
125	  // Each non-default type is its own save contract — pin its bytes so a future
126	  // refactor can't silently corrupt worlds created with it. Re-baseline only on
127	  // a deliberate, CHANGELOG-flagged change to that type (same policy as default).
128	  test.each([
129	    ["flat", "28e1e3ea69e01b02b8452f27bf88acc8a7b81edcfe24a4293363553379d072d3"],
130	    ["amplified", "87ff8cb4f73247a6e62bfc7c8638c86cfa7cfe8a5d90185d6773d390067540a0"],
131	    ["islands", "e9937c0d947a0952130c79c46c26fc37c9492c7d164e2dc61a626ea9d7d8a662"]
132	  ] as Array<[WorldType, string]>)("128x150x128 %s world for seed 1337 is byte-identical", (worldType, expected) => {
133	    expect(hashBytes(makeTypedWorld(128, 150, 128, 1337, worldType).blocks)).toBe(expected);
134	  });
135	
136	  test("flat is nearly level; amplified has more relief than default", () => {
137	    const flat = makeTypedWorld(128, 150, 128, 1337, "flat");
138	    const def = makeTypedWorld(128, 150, 128, 1337, "default");
139	    const amp = makeTypedWorld(128, 150, 128, 1337, "amplified");
140	
141	    // Fraction of columns whose ground surface sits exactly at the flat height,
142	    // and the overall height spread. (Caves nibble the surface — denser in this
143	    // small test world than at full size — so flat isn't perfectly uniform, but
144	    // it concentrates at y=48 far more than the varied default terrain does.)
145	    const flatTarget = 48;
146	    const stats = (w: VoxelWorld) => {
147	      let lo = Infinity;
148	      let hi = -Infinity;
149	      let atTarget = 0;
150	      let total = 0;
151	      for (let x = 8; x < w.sizeX - 8; x += 4) {
152	        for (let z = 8; z < w.sizeZ - 8; z += 4) {
153	          const h = groundHeight(w, x, z);
154	          lo = Math.min(lo, h);
155	          hi = Math.max(hi, h);
156	          if (h === flatTarget) atTarget += 1;
157	          total += 1;
158	        }
159	      }
160	      return { range: hi - lo, fracAtTarget: atTarget / total };
161	    };
162	
163	    const f = stats(flat);
164	    const d = stats(def);
165	    const a = stats(amp);
166	
167	    expect(f.fracAtTarget).toBeGreaterThan(0.4); // flat ground concentrates at y=48
168	    expect(f.fracAtTarget).toBeGreaterThan(d.fracAtTarget * 3); // far more than default's spread terrain
169	    expect(d.range).toBeGreaterThan(30); // default terrain spans a wide height band
170	    expect(a.range).toBeGreaterThan(d.range); // amplified is more dramatic still
171	  });
172	
173	  test("islands floods more of the map than default but still leaves dry land above the sea", () => {
174	    const islands = makeTypedWorld(128, 150, 128, 1337, "islands");
175	    const def = makeTypedWorld(128, 150, 128, 1337, "default");
176	    const ISLANDS_SEA = 54;
177	
178	    const waterColumns = (w: VoxelWorld, sea: number) => {
179	      let wet = 0;
180	      let total = 0;
181	      for (let x = 8; x < w.sizeX - 8; x += 4) {
182	        for (let z = 8; z < w.sizeZ - 8; z += 4) {
183	          total += 1;
184	          if (groundHeight(w, x, z) < sea) wet += 1;
185	        }
186	      }
