190	    expect(waterColumns(islands, ISLANDS_SEA)).toBeGreaterThan(waterColumns(def, 43));
191	    expect(waterColumns(islands, ISLANDS_SEA)).toBeGreaterThan(0.2);
192	
193	    // Dry, standable land above the sea exists (so the spawn search has somewhere to land).
