import { BiomeId, BlockId, VoxelWorld, generateWorld } from "@/lib/world";

for (const [seed, size] of [
  [1337, 128],
  [1, 128],
  [999999937, 128],
  [1337, 512]
] as const) {
  const world = new VoxelWorld(size, 150, size, seed);
  generateWorld(world);
  let ocean = 0;
  let eligible = 0;
  let kelp = 0;
  let coral = 0;
  let topKelpMaxY = -1;
  for (let x = 4; x < size - 4; x += 1) {
    for (let z = 4; z < size - 4; z += 1) {
      if (world.getBiome(x, z) !== BiomeId.Ocean) continue;
      ocean += 1;
      for (let y = 0; y < 150; y += 1) {
        const b = world.get(x, y, z);
        if (b === BlockId.Kelp) {
          kelp += 1;
          if (y > topKelpMaxY) topKelpMaxY = y;
        } else if (b === BlockId.CoralPink || b === BlockId.CoralBlue) coral += 1;
      }
    }
  }
  console.log({ seed, size, ocean, kelp, coral, topKelpMaxY });
}

