1	import * as THREE from "three";
2	import { collidesAt, voxelRaycast } from "@/lib/world";
3	import {
4	  ARROW_TTL,
5	  BOSS_ARROW_DAMAGE,
6	  BOSS_ARROW_SPEED,
7	  BOSS_MELEE_DAMAGE,
8	  BOSS_MELEE_REACH,
9	  BOSS_MINION_CAP,
10	  BOSS_SPREAD,
11	  BOSS_SUMMON_INTERVAL_SECONDS,
12	  CREEPER_ABORT_RANGE,
13	  CREEPER_EXPLOSION_POWER,
14	  CREEPER_FUSE_RANGE,
15	  CREEPER_FUSE_SECONDS,
16	  HOSTILE_BURN_ABOVE_DAYLIGHT,
17	  HOSTILE_CAP,
18	  MOB_ARROW_KNOCKBACK,
19	  MOB_RETARGET_SECONDS,
20	  MOB_VS_MOB_KNOCKBACK,
21	  MOB_VS_MOB_REACH,
22	  PET_FOLLOW_MAX,
23	  PET_TELEPORT_DISTANCE,
24	  SKELETON_ARROW_DAMAGE,
25	  SKELETON_ARROW_SPEED,
26	  SKELETON_FIRE_VGAP,
27	  SKELETON_LEAD_FACTOR,
28	  SKELETON_STANDOFF_MAX,
29	  SKELETON_STANDOFF_MIN,
30	  SPIDER_AGGRO_BELOW_DAYLIGHT,
31	  VILLAGER_FLEE_RANGE
32	} from "@/lib/game/config";
33	import { MOB_TEMPLATES } from "@/lib/game/mobs";
34	import type { MobFaction } from "@/lib/game/types";
35	import { mobsThreaten } from "@/lib/game/gameModes";
36	import { mobDamageMultiplier } from "@/lib/game/difficulties";
37	import type { EmitGameEvent, GameState, MobState } from "../state";
38	import { spawnArrow } from "../projectiles";
39	import { explode } from "./explosion";
40	import { pushMob } from "./spawnDirector";
41	import type { SurfaceYAtFn } from "@/lib/game/spawn";
42	
43	// Scratch vectors — per-frame tick over every mob must not allocate.
44	const UP = new THREE.Vector3(0, 1, 0);
45	const scratchToPlayer = new THREE.Vector3();
46	const scratchToPlayer3D = new THREE.Vector3();
47	const scratchMobEye = new THREE.Vector3();
48	const scratchPlayerAim = new THREE.Vector3();
49	const scratchRay = new THREE.Vector3();
50	const scratchMobFeet = new THREE.Vector3();
51	const scratchAim = new THREE.Vector3();
52	const scratchToTarget = new THREE.Vector3();
53	
54	const NO_ENEMIES: ReadonlySet<MobFaction> = new Set<MobFaction>();
55	
56	/**
57	 * The shared enmity table — which factions each faction will attack. "Fighters"
58	 * (hostile/raider/ally) hunt enemy-faction mobs; wild animals and villagers never
59	 * fight. Hostiles & raiders go after villagers and pets; pets defend against
60	 * hostiles & raiders.
61	 */
62	const ENEMY_FACTIONS: Record<MobFaction, ReadonlySet<MobFaction>> = {
63	  wild: NO_ENEMIES,
64	  villager: NO_ENEMIES,
65	  hostile: new Set<MobFaction>(["villager", "ally"]),
66	  raider: new Set<MobFaction>(["villager", "ally"]),
67	  ally: new Set<MobFaction>(["hostile", "raider"])
68	};
69	
70	/** Factions a villager flees from. */
71	const THREAT_FACTIONS: ReadonlySet<MobFaction> = new Set<MobFaction>(["hostile", "raider"]);
72	
73	/**
74	 * Victim factions whose death credits the player with loot + XP. A pet's kill
75	 * still feeds you ("your wolf hunts for you"); a slain villager or pet yields
76	 * nothing — which also closes the XP leak of farming mobs that kill each other.
77	 */
78	const CREDITED_FACTIONS: ReadonlySet<MobFaction> = new Set<MobFaction>(["wild", "hostile", "raider"]);
79	
80	function horizDistSq(a: MobState, b: MobState): number {
81	  const dx = a.position.x - b.position.x;
82	  const dz = a.position.z - b.position.z;
83	  return dx * dx + dz * dz;
84	}
85	
86	function mobById(state: GameState, id: number): MobState | null {
87	  for (const other of state.mobs) if (other.id === id) return other;
88	  return null;
89	}
90	
91	/**
92	 * The mob (if any) this fighter is hunting. It keeps its cached `targetId` while
93	 * that mob is alive, still an enemy, and in range; otherwise it re-scans for the
94	 * nearest enemy-faction mob — but only every MOB_RETARGET_SECONDS, so the per-mob
95	 * tick stays O(N) and full scans amortize to ~1–2 Hz per fighter. Non-fighters
96	 * (wild/villager) have no enemies and return null immediately.
97	 */
98	function selectMobTarget(state: GameState, mob: MobState): MobState | null {
99	  const enemies = ENEMY_FACTIONS[mob.faction];
100	  if (enemies.size === 0) return null;
101	  const rangeSq = mob.detectRange * mob.detectRange;
102	  if (mob.targetId !== null && mob.retargetTimer > 0) {
103	    const cached = mobById(state, mob.targetId);
104	    if (cached && cached.hp > 0 && enemies.has(cached.faction) && horizDistSq(mob, cached) < rangeSq) return cached;
105	  }
106	  mob.retargetTimer = MOB_RETARGET_SECONDS;
107	  let best: MobState | null = null;
108	  let bestSq = rangeSq;
109	  for (const other of state.mobs) {
110	    if (other === mob || other.hp <= 0 || !enemies.has(other.faction)) continue;
111	    const d = horizDistSq(mob, other);
112	    if (d < bestSq) {
113	      bestSq = d;
114	      best = other;
115	    }
116	  }
117	  mob.targetId = best ? best.id : null;
118	  return best;
119	}
120	
121	/** Nearest hostile/raider within `range` of a villager (drives its flee), or null. */
122	function nearestThreat(state: GameState, mob: MobState, range: number): MobState | null {
123	  let best: MobState | null = null;
124	  let bestSq = range * range;
125	  for (const other of state.mobs) {
126	    if (other.hp <= 0 || !THREAT_FACTIONS.has(other.faction)) continue;
127	    const d = horizDistSq(mob, other);
128	    if (d < bestSq) {
129	      bestSq = d;
130	      best = other;
131	    }
132	  }
133	  return best;
134	}
135	
136	/** True when nothing solid blocks the segment from a fighter's eye to its target — so it can't bite through a wall/door. */
137	function mobVsMobLineOfSight(world: GameState["world"], mob: MobState, dx: number, dy: number, dz: number): boolean {
138	  scratchRay.set(dx, dy, dz);
139	  if (scratchRay.lengthSq() <= 1e-6) return true;
140	  const dist = scratchRay.length();
141	  scratchMobEye.set(mob.position.x, mob.position.y + mob.halfHeight * 0.35, mob.position.z);
142	  return voxelRaycast(world, scratchMobEye, scratchRay.normalize(), dist) === null;
143	}
144	
145	/**
146	 * A ranged mob looses an arrow from its eye toward the player's chest, leading a
147	 * moving target by a fraction of the arrow's travel time. The arrow is not
148	 * player-owned, so it only ever hits the player (never the firer or other mobs).
149	 */
150	function fireMobArrow(state: GameState, mob: MobState, damage: number, speed: number, emit: EmitGameEvent): void {
151	  const { player } = state;
152	  const eyeY = mob.position.y + mob.halfHeight * 0.7;
153	  const dist = Math.hypot(player.position.x - mob.position.x, player.position.z - mob.position.z);
154	  const lead = (dist / speed) * SKELETON_LEAD_FACTOR;
155	  scratchAim.set(
156	    player.position.x + player.velocity.x * lead - mob.position.x,
157	    player.position.y + 0.9 - eyeY,
158	    player.position.z + player.velocity.z * lead - mob.position.z
159	  );
160	  spawnArrow(state, mob.position.x, eyeY, mob.position.z, scratchAim, {
161	    speed,
162	    damage,
163	    knockback: MOB_ARROW_KNOCKBACK,
164	    fromPlayer: false,
165	    ttl: ARROW_TTL
166	  });
167	  emit({ type: "mobAttacked", kind: mob.kind });
168	}
169	
170	/** The boss looses a 3-arrow horizontal spread aimed at the player's chest. */
171	function fireBossSpread(state: GameState, mob: MobState, dmgScale: number, emit: EmitGameEvent): void {
172	  const { player } = state;
173	  const eyeY = mob.position.y + mob.halfHeight * 0.7;
174	  const baseX = player.position.x - mob.position.x;
175	  const baseY = player.position.y + 0.9 - eyeY;
176	  const baseZ = player.position.z - mob.position.z;
177	  for (let spread = -1; spread <= 1; spread += 1) {
178	    scratchAim.set(baseX, baseY, baseZ);
179	    if (spread !== 0) scratchAim.applyAxisAngle(UP, spread * BOSS_SPREAD);
180	    spawnArrow(state, mob.position.x, eyeY, mob.position.z, scratchAim, {
181	      speed: BOSS_ARROW_SPEED,
182	      damage: BOSS_ARROW_DAMAGE * dmgScale,
183	      knockback: MOB_ARROW_KNOCKBACK,
184	      fromPlayer: false,
185	      ttl: ARROW_TTL
186	    });
187	  }
188	  emit({ type: "mobAttacked", kind: mob.kind });
189	}
190	
191	/**
192	 * The boss periodically conjures a skeleton or zombie nearby while it is engaged,
193	 * up to its own minion cap and the shared global hostile cap.
194	 */
195	function tickBossSummon(state: GameState, mob: MobState, dt: number, deps: MobTickDeps): void {
196	  mob.summonTimer = (mob.summonTimer ?? 0) - dt;
197	  if (mob.summonTimer > 0) return;
198	  mob.summonTimer = BOSS_SUMMON_INTERVAL_SECONDS;
199	
200	  let minions = 0;
201	  let hostiles = 0;
202	  for (const other of state.mobs) {
203	    if (!other.hostile) continue;
204	    hostiles += 1;
205	    if (other.kind !== "boss") minions += 1;
206	  }
207	  if (minions >= BOSS_MINION_CAP || hostiles >= HOSTILE_CAP) return;
208	
209	  const kind = deps.rng() < 0.5 ? "skeleton" : "zombie";
210	  const angle = deps.rng() * Math.PI * 2;
211	  const radius = 2 + deps.rng() * 2;
212	  const mx = mob.position.x + Math.cos(angle) * radius;
213	  const mz = mob.position.z + Math.sin(angle) * radius;
214	  const my = deps.surfaceYAt(mx, mz);
215	  pushMob(state, kind, true, mx, my, mz, deps.rng);
216	  deps.emit({ type: "mobSpawned", kind, x: mx, y: my, z: mz });
217	}
218	
219	export type MobTickDeps = {
220	  surfaceYAt: SurfaceYAtFn;
221	  applyDamage: (amount: number) => void;
222	  /** Removes the mob (post-loop sweep). `credit` (default true) gates loot + XP to the player. */
223	  removeMobAt: (index: number, lootingLevel?: number, credit?: boolean) => void;
224	  rng: () => number;
225	  emit: EmitGameEvent;
226	};
227	
228	export function tickMobs(state: GameState, dt: number, deps: MobTickDeps): void {
229	  const { world, daylight, mobs, isDead } = state;
230	  const playerPosition = state.player.position;
231	  const playerVelocity = state.player.velocity;
232	  // Creative/Spectator players aren't a threat target — hostiles ignore them
233	  // entirely (no aggro, attacks, fuses, or summons), so they just wander.
234	  const threatened = mobsThreaten(state.gameMode);
235	  // Difficulty scales every hit a mob lands (melee + arrows): Easy 0.5×, Hard 1.5×.
236	  // Applied here at the strike, never by mutating the per-mob templates.
237	  const dmgScale = mobDamageMultiplier(state.difficulty);
238	
239	  for (let i = 0; i < mobs.length; i += 1) {
240	    const mob = mobs[i];
241	    // A mob killed earlier this tick (e.g. by an explosion) still awaits the
242	    // post-loop sweep — skip its AI so a corpse can't move or land a final hit.
243	    if (mob.hp <= 0) continue;
244	    mob.attackTimer -= dt;
245	    mob.turnTimer -= dt;
246	    mob.retargetTimer -= dt;
247	    const activeHostile = threatened && mob.hostile && (mob.kind !== "spider" || daylight < SPIDER_AGGRO_BELOW_DAYLIGHT);
248	
249	    scratchToPlayer.copy(playerPosition).sub(mob.position).setY(0);
250	    const distanceToPlayer = scratchToPlayer.length();
251	    scratchToPlayer3D.copy(playerPosition).sub(mob.position);
252	    const attackDistance = scratchToPlayer3D.length();
253	    const verticalGap = Math.abs(scratchToPlayer3D.y);
254	    let moveSpeed = mob.speed;
255	    const isBoss = mob.kind === "boss";
256	    const isRanged = MOB_TEMPLATES[mob.kind].ranged === true;
257	    let moveSign = 1;
258	
259	    // A fighter that isn't chasing the player hunts the nearest enemy-faction mob
260	    // (a hostile after a villager, a pet after a hostile). Creepers stay
261	    // player-focused — they detonate rather than bite. A sitting pet does nothing.
262	    const sitting = mob.sitting === true;
263	    const playerAggro = activeHostile && distanceToPlayer < mob.detectRange;
264	    const mobTarget = !sitting && !playerAggro && mob.kind !== "creeper" ? selectMobTarget(state, mob) : null;
265	
266	    if (sitting) {
267	      moveSpeed = 0; // a told-to-stay pet holds its ground
268	    } else if (playerAggro) {
269	      if (distanceToPlayer > 0.001) mob.direction.lerp(scratchToPlayer.normalize(), 0.2).normalize();
270	      moveSpeed *= 1.15;
271	      // Skeletons kite (back off / hold in a standoff band); the boss bears down.
272	      if (isRanged && !isBoss) {
273	        if (distanceToPlayer < SKELETON_STANDOFF_MIN) moveSign = -1;
274	        else if (distanceToPlayer <= SKELETON_STANDOFF_MAX) moveSign = 0;
275	      }
276	    } else if (mobTarget) {
277	      scratchToTarget.copy(mobTarget.position).sub(mob.position).setY(0);
278	      if (scratchToTarget.lengthSq() > 1e-6) mob.direction.lerp(scratchToTarget.normalize(), 0.2).normalize();
279	      moveSpeed *= 1.15;
280	    } else if (mob.faction === "ally") {
281	      // A pet with no enemy nearby follows its owner: recalled (teleported) when it
282	      // strays too far, jogging to catch up otherwise, and milling about up close.
283	      if (distanceToPlayer > PET_TELEPORT_DISTANCE) {
284	        const tx = playerPosition.x + (deps.rng() - 0.5) * 2;
285	        const tz = playerPosition.z + (deps.rng() - 0.5) * 2;
286	        mob.position.set(tx, deps.surfaceYAt(tx, tz) + mob.halfHeight, tz);
287	        mob.moveSpeed = mob.speed;
288	        continue; // recalled to the owner — skip the rest of this tick
289	      }
290	      if (distanceToPlayer > PET_FOLLOW_MAX) {
291	        if (distanceToPlayer > 0.001) mob.direction.lerp(scratchToPlayer.normalize(), 0.2).normalize();
292	        moveSpeed *= 1.3;
293	      } else if (mob.turnTimer <= 0) {
294	        mob.direction.applyAxisAngle(UP, (deps.rng() - 0.5) * Math.PI).normalize();
295	        mob.turnTimer = 1.5 + deps.rng() * 4;
296	      }
297	    } else if (mob.faction === "villager") {
298	      // Villagers don't fight — they flee the nearest hostile/raider, else mill about.
299	      const threat = nearestThreat(state, mob, VILLAGER_FLEE_RANGE);
300	      if (threat) {
301	        scratchToTarget.copy(mob.position).sub(threat.position).setY(0);
302	        if (scratchToTarget.lengthSq() > 1e-6) mob.direction.lerp(scratchToTarget.normalize(), 0.2).normalize();
303	        moveSpeed *= 1.3;
304	      } else if (mob.turnTimer <= 0) {
305	        mob.direction.applyAxisAngle(UP, (deps.rng() - 0.5) * Math.PI).normalize();
306	        mob.turnTimer = 1.5 + deps.rng() * 4;
307	      }
308	    } else if (!mob.hostile && distanceToPlayer < 4.2) {
309	      // Wild animals flee when you get close (villagers are handled above).
310	      if (distanceToPlayer > 0.001) mob.direction.lerp(scratchToPlayer.normalize().multiplyScalar(-1), 0.2).normalize();
311	      moveSpeed *= 1.15;
312	    } else if (mob.turnTimer <= 0) {
313	      mob.direction.applyAxisAngle(UP, (deps.rng() - 0.5) * Math.PI).normalize();
314	      mob.turnTimer = 1.5 + deps.rng() * 4;
315	    }
316	    mob.moveSpeed = moveSpeed;
317	
318	    let nx = mob.position.x + mob.direction.x * moveSpeed * dt * moveSign;
319	    let nz = mob.position.z + mob.direction.z * moveSpeed * dt * moveSign;
320	
321	    if (nx < 2 || nz < 2 || nx > world.sizeX - 2 || nz > world.sizeZ - 2) {
322	      mob.direction.multiplyScalar(-1);
323	      nx = mob.position.x + mob.direction.x * moveSpeed * dt * moveSign;
324	      nz = mob.position.z + mob.direction.z * moveSpeed * dt * moveSign;
325	      mob.turnTimer = 1;
326	    }
327	
328	    let ground = deps.surfaceYAt(nx, nz);
329	    scratchMobFeet.set(nx, ground, nz);
330	    if (collidesAt(world, scratchMobFeet, 0.28, mob.halfHeight * 2)) {
331	      mob.direction.multiplyScalar(-1);
332	      nx = mob.position.x;
333	      nz = mob.position.z;
334	      ground = mob.position.y - mob.halfHeight;
335	      mob.turnTimer = 1;
336	    }
337	    mob.position.set(nx, ground + mob.halfHeight, nz);
338	    mob.yaw = Math.atan2(mob.direction.x, mob.direction.z);
339	
340	    // Ranged mobs shoot from across their detect range; melee mobs (and the boss
341	    // up close) must be adjacent. The boss reaches a little farther for melee.
342	    const meleeReach = isBoss ? BOSS_MELEE_REACH : 4;
343	    const meleeVGap = isBoss ? SKELETON_FIRE_VGAP : 1.6;
344	    const meleeReady = activeHostile && attackDistance < meleeReach && verticalGap < meleeVGap;
345	    const fireReady = isRanged && activeHostile && attackDistance < mob.detectRange && verticalGap < SKELETON_FIRE_VGAP;
346	    // A creeper close enough to light its fuse also needs a line-of-sight check —
347	    // it can be in range with a large vertical gap (so not meleeReady), which
348	    // would otherwise arm the fuse off the default `hasLineOfSight = true`.
349	    const creeperFuseReady = mob.kind === "creeper" && activeHostile && attackDistance < CREEPER_FUSE_RANGE;
350	
351	    let hasLineOfSight = true;
352	    if (meleeReady || fireReady || creeperFuseReady) {
353	      scratchMobEye.set(mob.position.x, mob.position.y + mob.halfHeight * 0.35, mob.position.z);
354	      scratchPlayerAim.set(playerPosition.x, playerPosition.y + 0.9, playerPosition.z);
355	      scratchRay.copy(scratchPlayerAim).sub(scratchMobEye);
356	      if (scratchRay.lengthSq() > 1e-6) {
357	        const hit = voxelRaycast(world, scratchMobEye, scratchRay.normalize(), attackDistance + 0.5);
358	        hasLineOfSight = hit === null;
359	      }
360	    }
361	
362	    // !isDead: mobs keep ticking through the respawn countdown, but attacking a
363	    // corpse should neither sound nor re-arm the attack cooldown.
364	    if (!isDead && (meleeReady || fireReady) && hasLineOfSight && mob.attackTimer <= 0) {
365	      // The boss bites when adjacent, otherwise looses a spread; skeletons only
366	      // ever shoot; melee mobs only ever bite. Creepers never bite — they detonate.
367	      const doMelee = meleeReady && (!isRanged || isBoss) && mob.kind !== "creeper";
368	      if (doMelee) {
369	        deps.emit({ type: "mobAttacked", kind: mob.kind });
370	        deps.applyDamage((isBoss ? BOSS_MELEE_DAMAGE : mob.attackDamage) * dmgScale);
371	        if (distanceToPlayer > 0.001) {
372	          scratchToPlayer.normalize().multiplyScalar(isBoss ? 6 : 4.2);
373	          playerVelocity.x += scratchToPlayer.x;
374	          playerVelocity.z += scratchToPlayer.z;
375	          playerVelocity.y = Math.max(playerVelocity.y, isBoss ? 4.5 : 3.4);
376	        }
377	      } else if (fireReady) {
378	        if (isBoss) fireBossSpread(state, mob, dmgScale, deps.emit);
379	        else fireMobArrow(state, mob, SKELETON_ARROW_DAMAGE * dmgScale, SKELETON_ARROW_SPEED, deps.emit);
380	      }
381	      mob.attackTimer = mob.attackCooldown;
382	    }
383	
384	    // Mob-vs-mob melee: a fighter with a live mob target bites it when adjacent.
385	    // Independent of the player (it happens through the respawn countdown too) and
386	    // of difficulty (dmgScale scales player-facing damage only). No LOS raycast —
387	    // A line-of-sight raycast (like the player-facing strike) stops a fighter from
388	    // biting through a thin wall or door when within reach. The kill is resolved by
389	    // the post-loop sweep, never mid-loop (splice-safety).
390	    if (mobTarget && mob.attackDamage > 0 && mob.attackTimer <= 0 && mobTarget.hp > 0) {
391	      const dx = mobTarget.position.x - mob.position.x;
392	      const dy = mobTarget.position.y - mob.position.y;
393	      const dz = mobTarget.position.z - mob.position.z;
394	      const horiz = Math.hypot(dx, dz);
395	      if (horiz < MOB_VS_MOB_REACH && Math.abs(dy) < 1.6 && mobVsMobLineOfSight(world, mob, dx, dy, dz)) {
396	        mobTarget.hp -= mob.attackDamage;
397	        if (horiz > 0.001) {
398	          const push = MOB_VS_MOB_KNOCKBACK / horiz;
399	          mobTarget.position.x += dx * push;
400	          mobTarget.position.z += dz * push;
401	        }
402	        deps.emit({ type: "mobAttacked", kind: mob.kind });
403	        mob.attackTimer = mob.attackCooldown;
404	      }
405	    }
406	
407	    // The boss conjures minions while it is engaged with the player.
408	    if (!isDead && isBoss && activeHostile && distanceToPlayer < mob.detectRange) {
409	      tickBossSummon(state, mob, dt, deps);
410	    }
411	
412	    // A creeper lights its fuse when it gets close, then detonates — destroying
413	    // terrain and hurting the player and nearby mobs. Walk out of range while it
414	    // is primed and the fuse aborts. It dies in its own blast (dropping gunpowder
415	    // via the post-loop sweep); killing it before the fuse runs out cancels it.
416	    if (!isDead && mob.kind === "creeper") {
417	      if ((mob.fuseTimer ?? 0) > 0) {
418	        if (!activeHostile || distanceToPlayer > CREEPER_ABORT_RANGE) {
419	          mob.fuseTimer = 0;
420	        } else {
421	          mob.fuseTimer = (mob.fuseTimer ?? 0) - dt;
422	          if (mob.fuseTimer <= 0) {
423	            explode(state, mob.position.x, mob.position.y, mob.position.z, CREEPER_EXPLOSION_POWER, deps);
424	            mob.hp = 0;
425	          }
426	        }
427	      } else if (creeperFuseReady && hasLineOfSight) {
428	        mob.fuseTimer = CREEPER_FUSE_SECONDS;
429	        deps.emit({ type: "mobAttacked", kind: "creeper" }); // the hiss
430	      }
431	    }
432	
433	    // Zombies, skeletons, and creepers burn in broad daylight; the boss is immune.
434	    if (mob.hostile && mob.kind !== "spider" && mob.kind !== "boss" && daylight > HOSTILE_BURN_ABOVE_DAYLIGHT) {
435	      mob.hp -= dt * 0.8;
436	    }
437	  }
438	
439	  // Sweep the dead after the loop (descending, so splices don't shift live
440	  // indices). A post-loop sweep — not per-iteration — also catches mobs killed by
441	  // an explosion (or another mob) earlier in the same pass, including the creeper
442	  // that just blew up. Loot + XP go to the player only for credited factions, so a
443	  // pet's kill feeds you but a slain villager/pet yields nothing.
444	  for (let i = mobs.length - 1; i >= 0; i -= 1) {
445	    const dead = mobs[i];
446	    if (dead.hp <= 0) deps.removeMobAt(i, 0, CREDITED_FACTIONS.has(dead.faction));
447	  }
448	}
