150	export function tickHostileSpawnDirector(state: GameState, dt: number, rng: () => number, surfaceYAt: SurfaceYAtFn): void {
151	  if (!hostilesSpawn(state.difficulty)) return;
152	  state.timers.hostileSpawnTimer += dt;
153	  const interval = HOSTILE_SPAWN_INTERVAL_SECONDS * hostileSpawnIntervalScale(state.difficulty);
