165	  spawnMobGroup(
166	    state,
167	    {
168	      kind,
169	      hostile: true,
170	      count: Math.min(cap - livingHostiles, 1 + (rng() > 0.7 ? 1 : 0)),
171	      centerX: state.player.position.x,
172	      centerZ: state.player.position.z,
173	      radius: Math.max(26, RENDER_RADIUS * 0.85),
174	      minRadius: HOSTILE_SPAWN_MIN_RADIUS
175	    },
176	    rng,
177	    surfaceYAt
178	  );
179	}
