2	import * as THREE from "three";
3	import { BlockId, VoxelWorld } from "@/lib/world";
4	import { CREEPER_FUSE_SECONDS, PET_FIGHT_RANGE } from "@/lib/game/config";
5	import { FACTION_BY_KIND, mobHalfHeight } from "@/lib/game/mobs";
