11	let nextMobId = 1;
12	
13	function makeMob(kind: MobKind, x: number, y: number, z: number, attackTimer = 0): MobState {
14	  return {
15	    id: nextMobId++, // unique, so targetId assertions can't accidentally resolve to the attacker
16	    kind,
17	    hostile: true,
18	    faction: FACTION_BY_KIND[kind],
19	    targetId: null,
20	    retargetTimer: 0,
21	    hp: 9,
22	    position: new THREE.Vector3(x, y, z),
23	    direction: new THREE.Vector3(0, 0, 1),
24	    yaw: 0,
25	    turnTimer: 5,
26	    speed: 1.08,
27	    moveSpeed: 1.08,
28	    detectRange: kind === "zombie" ? 11 : 12,
29	    attackDamage: 3,
30	    attackCooldown: 1.8,
31	    attackTimer,
32	    halfHeight: mobHalfHeight(kind),
33	    bobSeed: 0,
34	    fedTimer: 0,
35	    ageTimer: 0
36	  };
37	}
38	
39	function makeState(mobs: MobState[]): GameState {
40	  const world = new VoxelWorld(48, 48, 48, 1);
41	  return {
42	    world,
43	    blockChanges: createBlockChangeTracker(world),
44	    primedTnt: new Map<number, number>(),
45	    worldMeshDirty: false,
46	    gameMode: "survival", // hostiles only threaten survival/adventure players
47	    difficulty: "normal", // baseline 1× mob-damage multiplier
48	    mobs,
49	    projectiles: [],
50	    nextProjectileId: 1,
51	    daylight: 0.1, // night-ish so hostiles stay active and don't burn
52	    player: { position: new THREE.Vector3(24, 30, 24), velocity: new THREE.Vector3(), yaw: 0, pitch: 0, onGround: true }
53	  } as unknown as GameState;
54	}
55	
56	function makeDeps() {
57	  const events: GameEvent[] = [];
58	  let damage = 0;
59	  const deps: MobTickDeps = {
60	    surfaceYAt: () => 29, // keeps mob.y ≈ player.y so the vertical gap stays small
61	    applyDamage: (a: number) => {
62	      damage += a;
63	    },
64	    removeMobAt: () => {},
65	    rng: () => 0.5,
66	    emit: (e: GameEvent) => events.push(e)
67	  };
68	  return { deps, events, getDamage: () => damage };
69	}
70	
71	describe("ranged skeletons", () => {
72	  test("a skeleton with line of sight fires an arrow and re-arms its cooldown", () => {
73	    const skeleton = makeMob("skeleton", 24, 30, 17); // ~7 blocks away, in the standoff band
74	    const state = makeState([skeleton]);
75	    const { deps, events } = makeDeps();
76	
77	    tickMobs(state, 0.05, deps);
78	
79	    expect(state.projectiles).toHaveLength(1);
80	    expect(state.projectiles[0].fromPlayer).toBe(false);
81	    expect(skeleton.attackTimer).toBeCloseTo(skeleton.attackCooldown, 5);
82	    expect(events.some((e) => e.type === "mobAttacked" && e.kind === "skeleton")).toBe(true);
83	  });
84	
85	  test("a skeleton kites away when the player is too close", () => {
86	    const skeleton = makeMob("skeleton", 24, 30, 21, 1); // 3 blocks away (< standoff min), cooldown not ready
87	    const state = makeState([skeleton]);
88	    const { deps } = makeDeps();
89	    const startZ = skeleton.position.z;
90	
91	    tickMobs(state, 0.05, deps);
92	
93	    // Player is at z=24; backing away means moving toward smaller z.
94	    expect(skeleton.position.z).toBeLessThan(startZ);
95	  });
