 * halfHeight mirrors mobHalfHeight's fish branch (body only, no leg clearance).
 */
function createFishModel(group: THREE.Group, materials: THREE.MeshStandardMaterial[], bodySize: [number, number, number], headSize: [number, number, number]): MobModel {
  const bodyGeo = new THREE.BoxGeometry(bodySize[0], bodySize[1], bodySize[2]);
