18	function mulberry32(seed: number): () => number {
19	  let t = seed >>> 0;
20	  return () => {
21	    t += 0x6d2b79f5;
22	    let r = Math.imul(t ^ (t >>> 15), 1 | t);
23	    r ^= r + Math.imul(r ^ (r >>> 7), 61 | r);
24	    return ((r ^ (r >>> 14)) >>> 0) / 4294967296;
25	  };
26	}
27	
28	function makeEngine(difficulty: Difficulty): GameEngine {
