10	/** Session-only camera presentation mode; never persisted. Gameplay stays eye-relative in all modes. */
11	export type CameraMode = "first" | "third-rear" | "third-front";
12	
13	const CAMERA_MODE_CYCLE: readonly CameraMode[] = ["first", "third-rear", "third-front"];
14	
15	export function nextCameraMode(mode: CameraMode): CameraMode {
16	  return CAMERA_MODE_CYCLE[(CAMERA_MODE_CYCLE.indexOf(mode) + 1) % CAMERA_MODE_CYCLE.length];
17	}
