19	export type PlayerState = {
20	  position: THREE.Vector3;
21	  velocity: THREE.Vector3;
22	  /** Look direction; the renderer derives the camera from these. Order YXZ. */
23	  yaw: number;
24	  pitch: number;
25	  onGround: boolean;
26	};
27	
28	/** Simulation-side mob — no Three.js objects; visuals live in the renderer. */
29	export type MobState = {
30	  id: number;
31	  kind: MobKind;
32	  hostile: boolean;
33	  /** Targeting allegiance (set at spawn from FACTION_BY_KIND; a tamed pet becomes "ally"). Persisted (save v14). */
34	  faction: MobFaction;
35	  /** Pet owner once tamed (currently always "player"); undefined for wild mobs. Persisted (save v14). */
36	  owner?: "player";
37	  /** A tamed pet told to stay put (sit/stay) — no follow, wander, or pursuit. Persisted (save v14). */
38	  sitting?: boolean;
39	  /** Villager-only: trade profession (drives its trade subset + tint). Persisted (save v15). */
40	  profession?: Profession;
41	  /** Session-only: id of the enemy mob this fighter is attacking, or null. Never serialized. */
42	  targetId: number | null;
43	  /** Session-only: seconds until the next enemy-mob rescan (throttle). Never serialized. */
44	  retargetTimer: number;
45	  hp: number;
46	  /** Body center (ground + halfHeight), like the old group.position without bob. */
47	  position: THREE.Vector3;
48	  direction: THREE.Vector3;
49	  yaw: number;
50	  turnTimer: number;
51	  speed: number;
52	  /** Speed after aggro/flee multipliers this tick; renderer uses it for gait. */
53	  moveSpeed: number;
54	  detectRange: number;
55	  attackDamage: number;
56	  attackCooldown: number;
57	  attackTimer: number;
58	  halfHeight: number;
59	  bobSeed: number;
60	  /** Seconds left "in love" after being fed; pairs with another to breed. */
61	  fedTimer: number;
62	  /** Seconds left as a baby; > 0 means a scaled-down, no-drop juvenile. */
63	  ageTimer: number;
64	  /** Boss-only: seconds until the next minion summon (session-only, never saved). */
65	  summonTimer?: number;
66	  /** Creeper-only: seconds left on a lit fuse (>0 means primed); detonates at 0. Session-only. */
67	  fuseTimer?: number;
68	};
69	
70	/**
71	 * Simulation-side projectile (arrow) — transient, never serialized, like mobs.
72	 * Shared by the player's bow, ranged skeletons, and the boss; `fromPlayer` is
73	 * the hit filter (player arrows hit mobs, mob arrows hit the player).
74	 */
75	export type ProjectileState = {
76	  id: number;
77	  position: THREE.Vector3;
78	  /** m/s; gravity-integrated each step. yaw/pitch are derived from it for the renderer. */
79	  velocity: THREE.Vector3;
80	  yaw: number;
81	  pitch: number;
82	  damage: number;
83	  knockback: number;
84	  fromPlayer: boolean;
