95	export type ThrownSpearState = {
96	  id: number;
97	  itemId: string;
98	  position: THREE.Vector3;
99	  velocity: THREE.Vector3;
100	  damage: number;
101	  age: number;
102	  /** Seconds embedded in terrain, or null while still flying. */
103	  stuckTimer: number | null;
104	};
105	
106	/**
107	 * The one active fishing cast — session-only, never serialized (like projectiles).
108	 * `timer` counts down to the next state change: while `!biting` it's the wait for a
109	 * bite; once `biting` it's the reel window before the catch gets away.
110	 */
111	export type FishingState = {
112	  position: THREE.Vector3;
113	  timer: number;
114	  biting: boolean;
115	};
116	
117	export type VehicleState = {
118	  id: number;
119	  kind: VehicleKind;
120	  position: THREE.Vector3;
121	  yaw: number;
