151	  effectPoisonTimer: number;
152	  stuckTimer: number;
153	  hostileSpawnTimer: number;
154	  aquaticSpawnTimer: number;
155	  spawnerTimer: number;
156	  daylightHudTimer: number;
157	  debugHudTimer: number;
158	  randomTickTimer: number;
159	  breedTimer: number;
160	  spearThrowCooldown: number;
161	  /** Seconds until the bow can fire again (instant click-to-fire rate limit). */
162	  bowCooldownTimer: number;
163	};
164	
165	export type WeatherKind = "clear" | "rain" | "snow";
166	export type WeatherState = { kind: WeatherKind; intensity: number };
167	
168	/**
169	 * An in-progress village raid — session-only, never serialized (like the boss).
170	 * A reload cancels it. Waves of raiders spawn around `center`; once a wave is
171	 * cleared, `waveTimer` counts down to the next, until all `totalWaves` are beaten.
172	 */
173	export type RaidState = {
174	  center: { x: number; z: number };
175	  /** Waves spawned so far (0 before the first spawns, up to totalWaves). */
176	  wavesSpawned: number;
177	  totalWaves: number;
178	  /** Seconds until the next wave once the current one is cleared. */
179	  waveTimer: number;
