  ],
  rare: [
    { itemId: "diamond_ore", min: 2, max: 4, chance: 0.6 },
    { itemId: "gold_sword", min: 1, max: 1, chance: 0.2 },
    { itemId: "chestplate", min: 1, max: 1, chance: 0.25 },
